package cn.edu.hust.mathdrill.family;
import cn.edu.hust.mathdrill.auth.AuthService;
import cn.edu.hust.mathdrill.practice.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service public class FamilyService {
 private final FamilyMapper mapper;private final PracticeMapper practices;private final PracticeService service;private final AuthService auth;private final JdbcTemplate db;private final ReviewPracticeService reviews;
 public FamilyService(FamilyMapper mapper,PracticeMapper practices,PracticeService service,AuthService auth,JdbcTemplate db,ReviewPracticeService reviews){this.mapper=mapper;this.practices=practices;this.service=service;this.auth=auth;this.db=db;this.reviews=reviews;}
 private ResponseStatusException error(HttpStatus status,String message){return new ResponseStatusException(status,message);}
 private long parent(Authentication a){return Long.parseLong(auth.requireRole(a,"PARENT").id());}
 private Map<String,Object> link(FamilyMapper.Link l){return Map.of("id",l.id.toString(),"parentId",l.parentId.toString(),"studentId",l.studentId.toString(),"state",l.state);}
 private List<Map<String,Object>> ids(List<Map<String,Object>> rows){for(var row:rows)for(var k:List.of("id","parentId","studentId"))if(row.get(k)!=null)row.put(k,row.get(k).toString());return rows;}
 private FamilyMapper.Link active(long p,long child){var l=mapper.pair(p,child);if(l==null||!"ACTIVE".equals(l.state))throw error(HttpStatus.FORBIDDEN,"FAMILY_INACTIVE: 请先取得学生确认的有效关联");return l;}
 @Transactional public Object relations(Authentication a){var p=auth.current(a);return switch(p.role()){case "PARENT"->ids(mapper.children(Long.parseLong(p.id())));case "STUDENT"->ids(mapper.parents(Long.parseLong(p.id())));default->throw error(HttpStatus.FORBIDDEN,"FORBIDDEN: 当前角色不参与家庭关联");};}
 @Transactional public Object request(Authentication a,String studentLogin){long p=parent(a);practices.lockStudent(p);Long child=mapper.student(studentLogin);if(child==null)throw error(HttpStatus.BAD_REQUEST,"STUDENT_NOT_FOUND: 请检查学生登录名");var l=mapper.pair(p,child);if(l==null){l=new FamilyMapper.Link();l.parentId=p;l.studentId=child;mapper.add(l);}l.state=Set.of("ACTIVE","PENDING").contains(l.state==null?"PENDING":l.state)?l.state==null?"PENDING":l.state:"PENDING";mapper.update(l);return link(l);}
 @Transactional public Object respond(Authentication a,long id,boolean accept){long child=Long.parseLong(auth.requireRole(a,"STUDENT").id());var l=mapper.lock(id);if(l==null||l.studentId!=child)throw error(HttpStatus.FORBIDDEN,"FORBIDDEN: 无法处理这条申请");if("ACTIVE".equals(l.state)&&accept)return link(l);if(!"PENDING".equals(l.state))throw error(HttpStatus.CONFLICT,"LINK_CHANGED: 申请状态已改变");l.state=accept?"ACTIVE":"REJECTED";mapper.update(l);return link(l);}
 @Transactional public Object unbind(Authentication a,long id,boolean confirm){if(!confirm)throw error(HttpStatus.BAD_REQUEST,"CONFIRM_REQUIRED: 请再次确认解除关联");var p=auth.current(a);var l=mapper.lock(id);long uid=Long.parseLong(p.id());if(l==null||!(p.role().equals("PARENT")&&l.parentId==uid||p.role().equals("STUDENT")&&l.studentId==uid))throw error(HttpStatus.FORBIDDEN,"FORBIDDEN: 无法解除这条关联");if(!Set.of("ACTIVE","UNBOUND").contains(l.state))throw error(HttpStatus.CONFLICT,"LINK_INACTIVE: 当前尚无有效关联");l.state="UNBOUND";mapper.update(l);return link(l);}
 @Transactional public Object preview(Authentication a,long child,PracticeService.Create input){long p=parent(a);active(p,child);return service.previewForParent(p,child,input);}
 private PracticeMapper.Practice ownPreview(long p,long id){var candidates=practices.byId(id);if(candidates==null||!Objects.equals(candidates.senderId,p))throw error(HttpStatus.FORBIDDEN,"FORBIDDEN: 无法操作这份任务");active(p,candidates.studentId);return candidates;}
 @Transactional public Object send(Authentication a,long id,boolean confirm){long p=parent(a);if(!confirm)throw error(HttpStatus.BAD_REQUEST,"CONFIRM_REQUIRED: 请确认发送对象和预览内容");var task=ownPreview(p,id);if(Set.of("PENDING","IN_PROGRESS","COMPLETED").contains(task.status))return service.taskSummary(task);if(!"PREVIEW".equals(task.status)||practices.ageMs(id)>900000)throw error(HttpStatus.CONFLICT,"PREVIEW_EXPIRED: 预览已失效，请重新生成并核对");
  practices.lockStudent(task.studentId);int recipientGrade=task.recipientGradeAtPreview==null?task.originalGrade:task.recipientGradeAtPreview;if(!Objects.equals(mapper.grade(task.studentId),recipientGrade))throw error(HttpStatus.CONFLICT,"PREVIEW_CHANGED: 学生在预览后已变更年级，请重新预览");
  var points=practices.practicePoints(id);if(points.isEmpty())points=List.of(Map.of("pointId",task.pointId,"pointRevision",task.pointRevision,"grade",task.originalGrade,"pointName",task.pointName));
  for(var snapshot:points){long pointId=Long.parseLong(snapshot.get("pointId").toString());var point=mapper.point(pointId);if(point==null||((Number)point.get("revision")).longValue()!=((Number)snapshot.get("pointRevision")).longValue()||!Boolean.TRUE.equals(point.get("enabled"))||((Number)point.get("grade")).intValue()!=((Number)snapshot.get("grade")).intValue()||!Objects.equals(point.get("name"),snapshot.get("pointName")))throw error(HttpStatus.CONFLICT,"PREVIEW_CHANGED: 知识点分类或启用状态已改变，请重新预览");}

  var items=new ArrayList<>(practices.items(id));items.sort(Comparator.comparing(i->i.questionId));for(var item:items){var q=mapper.question(item.questionId);if(q==null||!Boolean.TRUE.equals(q.get("enabled"))||!Boolean.TRUE.equals(q.get("reviewed"))||((Number)q.get("revision")).longValue()!=item.sourceRevision)throw error(HttpStatus.CONFLICT,"PREVIEW_CHANGED: 题目版本或可用状态已改变，请重新预览");}
  task=practices.lock(id,task.studentId);if(!"PREVIEW".equals(task.status))return service.taskSummary(task);task.status="PENDING";practices.update(task);return service.taskSummary(task);
 }
 @Transactional public Object withdraw(Authentication a,long id,boolean confirm){long p=parent(a);if(!confirm)throw error(HttpStatus.BAD_REQUEST,"CONFIRM_REQUIRED: 请再次确认撤回");var preview=ownPreview(p,id);var task=practices.lock(id,preview.studentId);if("WITHDRAWN".equals(task.status))return service.taskSummary(task);if(!"PENDING".equals(task.status))throw error(HttpStatus.CONFLICT,"TASK_STARTED: 仅可撤回尚未开始的任务");task.status="WITHDRAWN";task.version++;practices.update(task);return service.taskSummary(task);}
 @Transactional public Object tasks(Authentication a,long child){active(parent(a),child);return Map.of("items",practices.list(child,100,0).stream().map(service::taskSummary).toList(),"total",practices.count(child));}
 @Transactional public Object view(Authentication a,long child,long task){active(parent(a),child);return service.readForParent(child,task);}
 @Transactional public Object mistakes(Authentication a,long child){active(parent(a),child);return service.mistakesForParent(child);}
 @Transactional public Object reviewOptions(Authentication a,long child,ReviewPracticeService.Selection input){active(parent(a),child);return reviews.optionsFor(child,input.itemIds());}
 @Transactional public Object reinforcementPreview(Authentication a,long child,ReviewPracticeService.ReinforceInput input){long p=parent(a);active(p,child);return reviews.parentPreview(p,child,input);}
 @Transactional public Object mistake(Authentication a,long child,long item){active(parent(a),child);return service.mistakeForParent(child,item);}
 @Transactional public Object stats(Authentication a,long child,String start,String end){active(parent(a),child);java.time.LocalDate from,to;var zone=java.time.ZoneId.of("Asia/Shanghai");try{to=end==null?java.time.LocalDate.now(zone):java.time.LocalDate.parse(end);from=start==null?to.minusDays(6):java.time.LocalDate.parse(start);if(from.isAfter(to))throw new IllegalArgumentException();}catch(Exception e){throw error(HttpStatus.BAD_REQUEST,"INVALID_DATE: 日期格式应为YYYY-MM-DD，开始日期不可晚于结束日期");}
  var begin=from.atStartOfDay(zone).withZoneSameInstant(java.time.ZoneOffset.UTC).toLocalDateTime();var finish=to.plusDays(1).atStartOfDay(zone).withZoneSameInstant(java.time.ZoneOffset.UTC).toLocalDateTime();
  String where=" FROM practice WHERE student_id=? AND status='COMPLETED' AND submitted_at>=? AND submitted_at<?";var summary=db.queryForMap("SELECT COUNT(*) completed,COALESCE(SUM(total),0) total,COALESCE(SUM(correct_count),0) correct,COALESCE(SUM(elapsed_ms),0) elapsedMs"+where,child,begin,finish);long quantity=((Number)summary.get("total")).longValue(),correct=((Number)summary.get("correct")).longValue();summary.put("accuracy",quantity==0?"":java.math.BigDecimal.valueOf(correct*100).divide(java.math.BigDecimal.valueOf(quantity),2,java.math.RoundingMode.HALF_UP).toPlainString());summary.put("start",from.toString());summary.put("end",to.toString());
  summary.put("days",db.queryForList("SELECT DATE_FORMAT(CONVERT_TZ(submitted_at,'+00:00','+08:00'),'%Y-%m-%d') day,SUM(total) total,SUM(correct_count) correct"+where+" GROUP BY day ORDER BY day",child,begin,finish));
  var points=db.queryForList("SELECT COALESCE(i.point_id,p.point_id) pointId,COALESCE(pp.point_name,p.point_name) pointName,p.original_grade grade,COUNT(*) total,SUM(CASE WHEN i.outcome='CORRECT' THEN 1 ELSE 0 END) correct FROM practice p JOIN practice_item i ON i.practice_id=p.id LEFT JOIN practice_point pp ON pp.practice_id=i.practice_id AND pp.point_id=i.point_id AND pp.point_revision=i.point_revision WHERE p.student_id=? AND p.status='COMPLETED' AND p.submitted_at>=? AND p.submitted_at<? GROUP BY pointId,pointName,grade",child,begin,finish);for(var point:points)point.put("pointId",point.get("pointId").toString());summary.put("points",points);return summary;
 }
}
